import 'dart:io';

import 'package:runfiles/runfiles.dart';
import 'package:test/test.dart';

import '../preset_file.dart';

void main() {
  group('presetFile', () {
    test('replaces the generator header and keeps the flags', () {
      const generated =
          '# Generated by bazelrc-preset.bzl\n'
          '# To update this file, run:\n'
          '#   bazel run @@overhead+//preset:generated.update\n'
          '\n'
          '# A flag.\n'
          'common --foo\n';
      expect(presetFile(generated), '$header\n# A flag.\ncommon --foo\n');
    });

    test('refuses output that does not start with the generator header', () {
      expect(
        () => presetFile('# Something else\n\ncommon --foo\n'),
        throwsFormatException,
      );
    });

    test('refuses a header with nothing after it', () {
      expect(
        () => presetFile('# Generated by bazelrc-preset.bzl\n'),
        throwsFormatException,
      );
    });

    test('takes the pinned generator\'s real output', () {
      final generated = File(
        Runfiles.create().rlocation(Platform.environment['GENERATED_PRESET']!),
      ).readAsStringSync();
      final file = presetFile(generated);
      expect(file, startsWith(header));
      expect(file, isNot(contains('@@')));
      expect(file, contains('\ncommon --'));
    });
  });

  group('staleness', () {
    test('passes the same content', () {
      expect(staleness('a\n', 'a\n'), isNull);
    });

    test('names a missing file and the command that writes it', () {
      expect(
        staleness(null, 'a\n'),
        allOf(contains('missing'), contains('bazel run @overhead//preset')),
      );
    });

    test('names a stale file and the command that writes it', () {
      expect(
        staleness('a\n', 'b\n'),
        allOf(contains('out of date'), contains('bazel run @overhead//preset')),
      );
    });
  });
}
